-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- 1. DANH MỤC LINH KIỆN (CATEGORIES)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 2. VỊ TRÍ KHO (STORE LOCATIONS) - 3 Vị trí chính
-- -----------------------------------------------------------------------------
ON CONFLICT (code) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 3. 20 MÃ LINH KIỆN ĐIỆN TỬ (PARTS)
-- -----------------------------------------------------------------------------
ON CONFLICT (ipn) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 4. TỒN KHO LÔ LINH KIỆN (PART_LOTS) - 20 BẢN GHI CHO MỖI VỊ TRÍ KHO
-- -----------------------------------------------------------------------------

-- 4.1. 20 bản ghi cho Vị trí LOC-A1 (Kệ A)
ON CONFLICT (lot_code) DO NOTHING;

-- 4.2. 20 bản ghi cho Vị trí LOC-B1 (Kệ B)
ON CONFLICT (lot_code) DO NOTHING;

-- 4.3. 20 bản ghi cho Vị trí LOC-C1 (Kệ C)
ON CONFLICT (lot_code) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 5. 20 BO MẠCH VẬT LÝ / THIẾT BỊ QR (BOARD_ITEMS) PHÂN BỔ TẠI CÁC VỊ TRÍ KHO
-- -----------------------------------------------------------------------------
ON CONFLICT (qr_code) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 6. NHẬT KÝ CHUYỂN DỊCH / NHẬP XUẤT KHO (STOCK_MOVEMENTS)
-- -----------------------------------------------------------------------------
ON CONFLICT DO NOTHING;

-- -----------------------------------------------------------------------------
-- 7. NHẬT KÝ MƯỢN TRẢ LINH KIỆN (PART_CHECKOUTS)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

COMMIT;
